window.THREADS["178221"] = {"tid": "178221", "title": "复活吧，我亲爱的JavTag！", "category": "交流", "typeid": "7", "author": "yy135798", "uid": "586046", "date": "2026-11-2 10:31:08", "views": 8509, "replies": 10, "pages_fetched": 1, "post_count": 11, "cover": "assets/images/178221/gEE3lEG.png", "all_images": ["assets/images/178221/gEE3lEG.png"], "pan": [{"key": "quark", "label": "夸克网盘"}], "pan_floor": [], "article": {"author": "yy135798", "uid": "586046", "avatar": "", "date": "2026-11-2 10:31:08", "html": "<font size=\"4\">好久没有整理存片了，打开JavTag，<font color=\"#ff0000\">bus怎么刮都失效。</font></font><br />\n<font size=\"4\">搜索论坛发现大家都碰到了这个问题，已经有人解决了，但是链接失效了，被逼无奈亲自动手。</font><br />\n<font size=\"4\">PS：我刚弄完大哥又重新续上了，他那个也可以。</font><br />\n<font size=\"4\"><br />\n</font><br />\n<font size=\"4\"><font color=\"#ff0000\">毕竟这可是我的挚爱亲朋，手足兄弟。所以，复活吧，我亲爱的JavTag！</font></font><br />\n<font size=\"4\"><font color=\"#ff0000\"><br />\n</font></font><br />\n<font size=\"4\">1.用dph做了一个bat，可以修复目前bus无法刮捎的问题。</font><br />\n<font size=\"4\">2.顺便修复了一下DB站封面图片在连刮时下载失败的问题，但是因为他限流太厉害了，所以效果可能不是很好。</font><br />\n<font size=\"4\">链接：<a href=\"https://pan.quark.cn/s/9769ac35cd8e?pwd=LegJ\" target=\"_blank\">https://pan.quark.cn/s/9769ac35cd8e?pwd=LegJ</a> </font><font size=\"4\">提取码：LegJ</font><br />\n<font size=\"4\"><br />\n</font><br />\n<font size=\"4\">顺便再发一次JavTag。因为可能不同版本无法修复。修复bat在压缩包里也有。</font><br />\n<font size=\"4\">链接：<a href=\"https://pan.quark.cn/s/c552db7c3779?pwd=rD4g\" target=\"_blank\">https://pan.quark.cn/s/c552db7c3779?pwd=rD4g</a> </font><font size=\"4\">提取码：rD4g</font><br />\n<font size=\"4\">有效期三十天。</font><br />\n<font size=\"4\">关于</font><font size=\"4\">JavTag怎么用不在赘述了，</font><font size=\"4\">可以观看原作者</font><font size=\"4\">@秋名山新手司机的帖子</font><br />\n<font size=\"4\"><br />\n顺便大家可以讨论一下需要添加什么简单的功能，我试试能不能...<font color=\"#ff0000\">让dph来干</font>。</font><br />\n<font size=\"4\"><br />\nPS：跑dp挺耗时间啊，前前后后各种修改，花了两个多小时了</font><br />\n<font size=\"4\">PS：链接总是失效就是因为酷酷下没人回，一看分享下载好几千，回复几十，干拿啊，搞得人没动力补链了。</font><br />\n<font size=\"4\"><br />\n</font><br />\n<br />\n<br />\n<img src=\"assets/images/178221/gEE3lEG.png\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\">", "images": ["assets/images/178221/gEE3lEG.png"]}, "comments": [{"floor": 2, "author": "csmkaka", "uid": "487237", "avatar": "", "date": "2026-11-2 11:13:03", "html": "虽然我没下 但是还是支持一波 分享使人进步", "images": []}, {"floor": 3, "author": "jse", "uid": "375354", "avatar": "", "date": "2026-11-2 11:29:07", "html": "DB刮削还是不行，javbus可以。", "images": []}, {"floor": 4, "author": "楓カレン好き", "uid": "580806", "avatar": "", "date": "2026-11-2 12:31:42", "html": "<i class=\"pstatus\"> 本帖最後由 楓カレン好き 於 2026-11-2 12:34 編輯 </i><br />\n<br />\n<font size=\"2\">有下原作者的版本 也有回复过，但是</font>还是支持一波 分享使人进步", "images": []}, {"floor": 5, "author": "black-sky", "uid": "429022", "avatar": "", "date": "2026-11-2 12:33:29", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4979664&amp;ptid=178221\" target=\"_blank\"><font color=\"#999999\">jse 發表於 2026-11-2 11:29</font></a></font><br />\nDB刮削还是不行，javbus可以。</blockquote></div><br />\n確實DB常常都會屏蔽掉短時高流量<br />\n還是JAVBUS比較大方", "images": []}, {"floor": 6, "author": "fzjfzj1979", "uid": "641520", "avatar": "", "date": "2026-11-2 12:40:06", "html": "我都看不懂了，哎，各位大哥都是技术人才，我落后了", "images": []}, {"floor": 7, "author": "flyingzsy0621", "uid": "322525", "avatar": "", "date": "2026-11-2 13:03:43", "html": "可以用javboss,加梯子很方便", "images": []}, {"floor": 8, "author": "陈伟佳", "uid": "682459", "avatar": "", "date": "2026-11-2 17:07:06", "html": "请问TAG是在哪里看版本？", "images": []}, {"floor": 9, "author": "虎虎生威", "uid": "507280", "avatar": "", "date": "2026-11-2 20:13:02", "html": "fc2有啥网站可以刮削吗？原来的网站挂了", "images": []}, {"floor": 10, "author": "ZGEN0210", "uid": "493475", "avatar": "", "date": "2026-11-2 20:25:35", "html": "最近一直在用javboss，对于我这种小白来说很友好", "images": []}, {"floor": 11, "author": "nttrd", "uid": "707311", "avatar": "", "date": "2026-11-3 09:53:12", "html": "这个还真没用过，迟点尝试一下", "images": []}]};
window.THREADS["178237"] = {"tid": "178237", "title": "有时候觉得找个夜场女当女友也不错", "category": "交流", "typeid": "7", "author": "giaogiaogiaog", "uid": "638358", "date": "2026-11-2 11:43:47", "views": 12414, "replies": 26, "pages_fetched": 2, "post_count": 27, "cover": "assets/images/178237/fEi9jf0.png", "all_images": ["assets/images/178237/fEi9jf0.png", "assets/images/178237/H3TUGdo.png"], "pan": [], "pan_floor": [], "article": {"author": "giaogiaogiaog", "uid": "638358", "avatar": "", "date": "2026-11-2 11:43:47", "html": "各人有各人看法，你说纹身逼，夜场逼 都是鸡，都是毒，我也不反对<br />\n<br />\n我个人觉得还好吧，有些女的也不是只要给钱就能出去日，也会挑人<br />\n<br />\n我认识这个刚开始约不出来，嘘寒问暖一番才日上<br />\n然后夜场女性生活丰富又骚，日起来是真爽<br />\n裤子一脱不用说就跪下去嗦鸡八，在镜子前不用说就知道抬脚到台面上露着逼等日<br />\n射完推走，我自己躺着抽烟，自己就会跑去厕所洗，洗回来我说给我嗦干净，就老老实实给我嗦干净<br />\n事后问了一下，无非就是初中不上学跑出来混夜场，跟自己姐姐住一起<br />\n我说我想日你姐双飞，她说不好意思说出口，你来我屋子自己跟我姐说<br />\n我说你闺蜜也好看，我也想日，当场就给她闺蜜打电话说有个帅哥在酒店来不来一起玩，给我都搞不好意思了<br />\n所以我想说的是找个夜场女在性生活方面是真的爽<br />\n至于你说当老婆，那我只能说随你了<img src=\"static/image/smiley/javbus/27.png\" smilieid=\"105\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" /><br />\n<br />\n<img src=\"assets/images/178237/fEi9jf0.png\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\">", "images": ["assets/images/178237/fEi9jf0.png"]}, "comments": [{"floor": 2, "author": "等等楼主", "uid": "458927", "avatar": "", "date": "2026-11-2 11:45:45", "html": "你这不是以找女友的名义找炮友吗", "images": []}, {"floor": 3, "author": "junkyo83", "uid": "423821", "avatar": "", "date": "2026-11-2 11:47:59", "html": "上不知道夜场妹妹好啊 玩一次开销太大了 这边出台2K起步", "images": []}, {"floor": 4, "author": "Northness", "uid": "579650", "avatar": "", "date": "2026-11-2 11:53:15", "html": "在注意安全的前提下，当个一日女友，当然可以，当老婆还是算了", "images": []}, {"floor": 5, "author": "DuoDo", "uid": "487260", "avatar": "", "date": "2026-11-2 11:56:15", "html": "当女朋友之后是不是不用给钱了", "images": []}, {"floor": 6, "author": "风景看不够", "uid": "560400", "avatar": "", "date": "2026-11-2 12:04:19", "html": "找夜场妹玩玩就行了，如果真的产生感情了，那吃亏的是你。夜场妹见的多，想的自然就开。没了你，她依然能遇到下一个炮友或者是老板", "images": []}, {"floor": 7, "author": "ffzlyuna", "uid": "533250", "avatar": "", "date": "2026-11-2 12:29:23", "html": "我就每个月跟一个妹妹玩，每次1400能玩一晚上，我觉得她很漂亮，三年了一直这么找她。最近家人生病我一直陪着家人，三个月没去找她，就把我删了", "images": []}, {"floor": 8, "author": "砸瓦鲁多", "uid": "367942", "avatar": "", "date": "2026-11-2 12:54:23", "html": "打着透免费批的算盘找炮友说是", "images": []}, {"floor": 9, "author": "lau123", "uid": "635166", "avatar": "", "date": "2026-11-2 12:56:43", "html": "羡慕了，居然还能给清理干净，从来没遇到过<img src=\"static/image/smiley/javbus/39.png\" smilieid=\"118\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 10, "author": "辛斯基1234", "uid": "376135", "avatar": "", "date": "2026-11-2 13:15:13", "html": "长得咋样", "images": []}, {"floor": 11, "author": "Antik123", "uid": "360230", "avatar": "", "date": "2026-11-2 13:18:42", "html": "包养一个啊正合适", "images": []}, {"floor": 12, "author": "Shepherdcin", "uid": "626846", "avatar": "", "date": "2026-11-2 13:38:23", "html": "这个虾线真不好看", "images": []}, {"floor": 13, "author": "我是风和", "uid": "383407", "avatar": "", "date": "2026-11-2 13:51:18", "html": "这话我现在赞同，能为你所用的就是好的！释放性欲和爱欲，最好是交易，别谈感情！", "images": []}, {"floor": 14, "author": "laco", "uid": "562437", "avatar": "", "date": "2026-11-2 14:31:10", "html": "“夜场女的归宿是老实人，高端的猎人往往以猎物的方式出现。你以为找到个听话女友，实际你这些东西在人家那屁都不是，一上来说两句就知道你目的了。”二十年前一位在本地夜场中很有份量的大佬跟我说的。", "images": []}, {"floor": 15, "author": "dada88888", "uid": "597661", "avatar": "", "date": "2026-11-2 15:12:24", "html": "看到帅哥两个字，就懂了，··没钱又不帅的可以退场了", "images": []}, {"floor": 16, "author": "mp4ba", "uid": "291666", "avatar": "", "date": "2026-11-2 15:17:48", "html": "当炮友可以，当女友就算了，迟早当绿帽。", "images": []}, {"floor": 17, "author": "sd371219", "uid": "85223", "avatar": "", "date": "2026-11-2 16:15:43", "html": "你这不是找女友。不给钱就是炮友，给钱就是嫖友。顺带还给你拉皮条。", "images": []}, {"floor": 18, "author": "Joker丶123", "uid": "560545", "avatar": "", "date": "2026-11-2 17:18:38", "html": "这种就是炮友，不是女友，千万得分清，人家都是走肾不走心的", "images": []}, {"floor": 19, "author": "taka", "uid": "304243", "avatar": "", "date": "2026-11-2 17:27:21", "html": "虽说性很重要，但谈到婚姻就别光扯裤裆里这点事了吧<img src=\"static/image/smiley/javbus/30.png\" smilieid=\"109\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 20, "author": "Solring", "uid": "626836", "avatar": "", "date": "2026-11-2 17:37:14", "html": "这种女的太low了，当你发现和她打炮没意思了，想尝试更高一点的精神生活时，会让你特别失望", "images": []}, {"floor": 21, "author": "cba1698", "uid": "381611", "avatar": "", "date": "2026-11-2 18:25:52", "html": "谈谈又不亏，也是体验一下罢了", "images": []}, {"floor": 22, "author": "Zkaaai", "uid": "427213", "avatar": "", "date": "2026-11-2 21:18:29", "html": "跳舞的比DJ好 这个约了一个多月 点不知道多少个舞才到手 现在就是给花篮 晚上就一起出去吃饭 活确实不错 这个抖音粉丝还不少呢", "images": []}, {"floor": 23, "author": "Zkaaai", "uid": "427213", "avatar": "", "date": "2026-11-2 21:19:31", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4980492&amp;ptid=178237\" target=\"_blank\"><font color=\"#999999\">Zkaaai 發表於 2026-11-2 21:18</font></a></font><br />\n跳舞的比DJ好 这个约了一个多月 点不知道多少个舞才到手 现在就是给花篮 晚上就一起出去吃饭 活确实不错 这 ...</blockquote></div><br />\n\n<br />\n<img src=\"assets/images/178237/H3TUGdo.png\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\">", "images": ["assets/images/178237/H3TUGdo.png"]}, {"floor": 24, "author": "Hawn", "uid": "437685", "avatar": "", "date": "2026-11-2 21:26:34", "html": "你是找炮友。。。跟女友没关系啊", "images": []}, {"floor": 25, "author": "xingyuan318", "uid": "430962", "avatar": "", "date": "2026-11-2 22:48:34", "html": "夜场的妹子比男的想的都开", "images": []}, {"floor": 26, "author": "zynova", "uid": "493841", "avatar": "", "date": "2026-11-2 23:05:25", "html": "情緒價值給足真的爽", "images": []}, {"floor": 27, "author": "wwzz9820", "uid": "405340", "avatar": "", "date": "2026-11-3 03:47:32", "html": "一般走心的叫女友和老婆，谁会管炮友，鸡，包养叫女友，更简单的区别，后者谁会带去见兄弟见家人", "images": []}]};
